-- Source: INTL_UN_SC_CONSOLIDATED_SANCTIONS (1011 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: ten columns below were bare try_to_date() calls -- a
-- pure-digit value would misread as epoch seconds instead of failing safely
-- (several of these, e.g. INDIVIDUAL_DATE_OF_BIRTH_YEAR/_NOTE, are free-text
-- generator-named fields that may not even hold real dates, which makes the
-- epoch-misread risk worse, not less, since a stray numeric note would
-- silently "parse"). No staging model matches this source at all, so wrapped
-- all ten bare casts in place. This model stays disabled (drop-list
-- duplicate, see above) -- fixed anyway since it's a landmine either way.

with source as (
    select * from {{ source('ripple_raw', 'INTL_UN_SC_CONSOLIDATED_SANCTIONS') }}
)

